    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    unordered_map<string, int> freq;
    for (int i = 0; i + 1 < n; ++i)
        ++freq[s.substr(i, 2)];

    string answer = s.substr(0, 2);
    for (int i = 0; i + 1 < n; ++i) {
        string pair = s.substr(i, 2);
        if (freq[pair] > freq[answer])
            answer = pair;
    }

    cout << answer << '\n';
    return 0;
}

