    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    int frequency[256][256] = {};
    int maxCount = 0;
    string answer;

    for (int i = 0; i + 1 < n; ++i) {
        unsigned char first = s[i];
        unsigned char second = s[i + 1];

        if (++frequency[first][second] > maxCount) {
            maxCount = frequency[first][second];
            answer = s.substr(i, 2);
        }
    }

    cout << answer << '\n';
    return 0;
}

